<template>
 <main class="shipyard-admin">
  <header class="workspace-header"><div><p class="eyebrow">船厂工程管理</p><h1>{{activeLabel}}</h1><p class="subtitle">{{data.user.name || '工作账号'}} · {{data.serverDate}} <span v-if="updated">数据更新于 {{updated}}</span></p></div><div class="workspace-controls"><el-select v-model="projectId" aria-label="当前工程" placeholder="选择工程"><el-option v-for="p in data.projects" :key="p.id" :label="p.name" :value="p.id"/></el-select><el-button :loading="loading" @click="act(refreshPage)">刷新数据</el-button></div></header>
  <nav class="workspace-nav" aria-label="船厂业务导航"><button v-for="tab in tabs" :key="tab.id" :class="{active:section===tab.id}" @click="navigate(tab.id)">{{tab.label}}</button></nav>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon><el-button link @click="act(refresh)">重新加载</el-button></el-alert>
  <el-skeleton v-if="!ready && loading" :rows="8" animated/>
  <el-empty v-else-if="!ready" description="工作数据尚未加载，请重试"/>
  <template v-else>
   <section v-if="section==='workbench'">
    <div class="table-heading"><h2>我的待办</h2><div class="actions"><el-button v-if="can('work:submit')" type="primary" @click="newRecord('用工')">新增用工</el-button><el-button v-if="can('expense:submit')" @click="newRecord('报销')">申请报销</el-button><el-button v-if="can('fine:submit')" @click="newRecord('罚款')">登记罚款</el-button></div></div>
    <p class="hint">{{tasks.length}} 项待处理。审批、付款和收款结果会同步到小程序与 H5。</p>
    <el-table :data="tasks" empty-text="当前工程暂无待处理事项" @row-click="showRecord"><el-table-column prop="title" label="事项"/><el-table-column prop="author" label="申请人" width="140"/><el-table-column prop="date" label="日期" width="140"/><el-table-column prop="status" label="当前状态"/><el-table-column label="金额"><template #default="{row}">¥{{money(row.amount)}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click.stop="showRecord(row)">查看处理</el-button></template></el-table-column></el-table>
    <template v-if="can('finance:view')"><div class="table-heading"><h2>工程经营情况</h2><span class="hint">包含已审批未付款成本</span></div><el-descriptions :column="3" border><el-descriptions-item label="合同总额">¥{{money(project?.price)}}</el-descriptions-item><el-descriptions-item label="已审批工资">¥{{money(project?.wages)}}</el-descriptions-item><el-descriptions-item label="两级已审批报销">¥{{money(project?.reimbursements)}}</el-descriptions-item><el-descriptions-item label="其他支出">¥{{money(project?.otherCosts)}}</el-descriptions-item><el-descriptions-item label="预计毛利">¥{{money((project?.price||0)-(project?.wages||0)-(project?.reimbursements||0)-(project?.otherCosts||0))}}</el-descriptions-item><el-descriptions-item label="实际资金余额">¥{{money(scoped(data.transactions).reduce((s,t)=>s+t.amount,0))}}</el-descriptions-item></el-descriptions></template>
   </section>
   <section v-else-if="section==='projects'">
    <div class="table-heading"><h2>工程与工作区域</h2><el-button v-if="can('master:edit')" type="primary" @click="editMaster('project')">新增工程</el-button></div>
    <el-table :data="data.projects"><el-table-column prop="name" label="船号"/><el-table-column prop="title" label="工程名称"/><el-table-column label="合同总价"><template #default="{row}">¥{{money(row.price)}}</template></el-table-column><el-table-column prop="area" label="面积 m²"/><el-table-column label="加班计薪"><template #default>同正常时薪</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="projectId=row.id">查看区域</el-button><el-button v-if="can('master:edit')" link type="primary" @click="editMaster('project',row)">编辑工程</el-button></template></el-table-column></el-table>
    <div class="table-heading"><h2>{{project?.name}} · 工作区域</h2><el-button v-if="can('master:edit') && project" @click="editMaster('area')">新增区域</el-button></div>
    <el-table :data="scoped(data.areas)"><el-table-column prop="name" label="区域"/><el-table-column prop="area" label="面积 m²"/><el-table-column prop="rate" label="结算单价"/><el-table-column prop="people" label="安排人数"/><el-table-column label="施工人员" min-width="160"><template #default="{row}">{{(row.workers||[]).map(w=>w.name).join('、')||'—'}}</template></el-table-column><el-table-column label="已批用工"><template #default="{row}">¥{{money(row.contract+row.wages)}}</template></el-table-column><el-table-column label="施工状态" min-width="150"><template #default="{row}">{{row.status}}<div v-if="row.completionRequestedAt&&!row.completedAt" class="hint">{{row.completionRequester||'组长'}} · {{row.completionRequestedAt}}</div></template></el-table-column><el-table-column label="操作" min-width="220"><template #default="{row}"><el-button v-if="can('master:edit')&&!row.completedAt" link @click="editMaster('area',row)">编辑区域</el-button><el-button v-if="can('work:submit')&&row.status==='进行中'" link :disabled="busy" @click="requestCompletion(row)">提交完工</el-button><el-button v-if="can('work:complete')&&row.completionRequestedAt&&!row.completedAt" link :disabled="busy" @click="rejectCompletion(row)">退回完工</el-button><el-button v-if="can('work:complete')&&!row.completedAt&&row.status!=='未开工'&&Number(row.completionRequestedBy)!==Number(data.user.id)" link type="primary" :disabled="busy" @click="complete(row)">确认完工</el-button></template></el-table-column></el-table>
    <div class="table-heading"><h2>工人与时薪</h2><el-button v-if="can('master:edit')" @click="editMaster('person')">新增人员</el-button></div><el-input v-model="personSearch" placeholder="搜索姓名、工号、班组" clearable class="search" aria-label="搜索人员"/><el-table :data="people"><el-table-column prop="name" label="姓名"/><el-table-column prop="code" label="工号"/><el-table-column prop="team" label="班组"/><el-table-column prop="rate" label="小时工资"/><el-table-column label="状态"><template #default="{row}">{{Number(row.active ?? 1)===1?'在职':'已停用'}}</template></el-table-column><el-table-column label="操作" min-width="180"><template #default="{row}"><template v-if="can('master:edit')"><el-button link type="primary" @click="editMaster('person',row)">编辑人员</el-button><el-button link :type="Number(row.active ?? 1)===1?'danger':'primary'" :disabled="busy" @click="toggleWorker(row)">{{Number(row.active ?? 1)===1?'停用人员':'恢复人员'}}</el-button></template></template></el-table-column></el-table>
   </section>
   <section v-else-if="section==='records'">
    <div class="table-heading"><h2>业务申请与审批</h2><div class="actions"><el-button v-if="can('work:submit')" type="primary" @click="newRecord('用工')">新增用工</el-button><el-button v-if="can('expense:submit')" @click="newRecord('报销')">申请报销</el-button><el-button v-if="can('fine:submit')" @click="newRecord('罚款')">登记罚款</el-button><el-button @click="exportRecords">导出申请</el-button></div></div>
    <div class="filters"><el-input v-model="search" placeholder="搜索单号、说明、申请人" clearable aria-label="搜索申请"/><el-select v-model="kind" aria-label="申请类型"><el-option label="全部类型" value=""/><el-option v-for="k in ['用工','报销','罚款']" :key="k" :label="k" :value="k"/></el-select><el-select v-model="recordAreaId" aria-label="工作区域筛选"><el-option label="全部区域" value=""/><el-option v-for="area in scoped(data.areas)" :key="area.id" :label="area.name" :value="area.id"/></el-select><el-select v-model="status" aria-label="申请状态"><el-option label="全部状态" value=""/><el-option v-for="s in statuses" :key="s" :label="s" :value="s"/></el-select><el-date-picker v-model="recordMonth" type="month" value-format="YYYY-MM" clearable placeholder="全部月份" aria-label="申请月份"/></div>
    <el-table :data="records" row-key="id"><el-table-column prop="title" label="申请" min-width="140"/><el-table-column prop="area" label="区域" min-width="150"/><el-table-column prop="author" label="申请人" width="110"/><el-table-column prop="date" label="日期" width="125"/><el-table-column prop="note" label="说明" min-width="180" show-overflow-tooltip/><el-table-column label="金额" width="130"><template #default="{row}">¥{{money(row.amount)}}</template></el-table-column><el-table-column prop="status" label="状态" min-width="140"/><el-table-column label="操作" width="100" fixed="right"><template #default="{row}"><el-button link type="primary" @click="showRecord(row)">查看详情</el-button></template></el-table-column></el-table>
   </section>
   <section v-else-if="section==='attendance'">
    <div class="table-heading"><h2>区域每日出勤</h2><el-button @click="exportAttendance">导出出勤</el-button></div><el-date-picker v-model="attendanceDate" value-format="YYYY-MM-DD" aria-label="出勤日期" placeholder="选择日期"/><p class="hint">按已审批的点工及加班记录统计，{{attendanceWorkers}} 人出勤。同一人不同区域分别列示。</p>
    <el-table :data="attendance"><el-table-column label="区域"><template #default="{row}">{{data.areas.find(a=>String(a.id)===String(row.areaId))?.name}}</template></el-table-column><el-table-column prop="name" label="工人"/><el-table-column prop="code" label="工号"/><el-table-column prop="team" label="班组"/><el-table-column prop="hours" label="工时（含加班）"/></el-table>
   </section>
   <section v-else-if="section==='archive'">
    <div class="table-heading"><h2>近三个月完工归档</h2><el-date-picker v-model="archiveMonth" type="month" value-format="YYYY-MM" placeholder="全部近三个月" clearable aria-label="归档月份"/></div>
    <el-table :data="archives"><el-table-column prop="name" label="工作区域"/><el-table-column prop="completedAt" label="完工时间"/><el-table-column label="已批用工金额"><template #default="{row}">¥{{money(row.contract+row.wages)}}</template></el-table-column><el-table-column label="工资结算"><template #default="{row}">{{row.paid?'已结清':'待结算'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link @click="recordAreaId=row.id;search='';kind='用工';status='';recordMonth='';navigate('records')">查看施工记录</el-button></template></el-table-column></el-table><p class="hint">完工不等于结清，历史单据仍保留在申请记录中。</p>
   </section>
   <section v-else-if="section==='payroll'">
    <div class="table-heading"><h2>工资结算</h2><el-button @click="exportPayroll">导出工资明细</el-button></div><div class="filters"><el-date-picker v-model="month" type="month" value-format="YYYY-MM" :clearable="false" aria-label="工资月份"/><span>选择合计 <strong>¥{{money(selectedTotal)}}</strong></span><el-button v-if="can('payroll:pay')" type="primary" :loading="busy" :disabled="!selected.length || !!error" @click="settle">确认工资结算</el-button></div>
    <el-table ref="payrollTable" :data="payroll" row-key="id" @selection-change="selected=$event"><el-table-column type="selection" width="45" :reserve-selection="true" :selectable="row=>!row.paid"/><el-table-column prop="name" label="工人"/><el-table-column prop="label" label="类型"/><el-table-column prop="hours" label="工时"/><el-table-column prop="rate" label="时薪快照"/><el-table-column prop="multiplier" label="倍率"/><el-table-column label="金额"><template #default="{row}">¥{{money(row.amount)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}">{{row.paid?'已结算':'待结算'}}</template></el-table-column></el-table>
   </section>
   <section v-else-if="section==='ledger'">
    <p v-if="!can('finance:view') && !can('payroll:pay')" class="hint">仅显示本人登记的其他收支，余额不代表整个工程。</p>
    <div class="table-heading"><h2>收支台账</h2><div><el-button v-if="can('ledger:edit')" type="primary" @click="openLedger">登记收支</el-button><el-button @click="exportLedger">导出台账</el-button></div></div><div class="filters"><el-date-picker v-model="month" type="month" value-format="YYYY-MM" :clearable="false" aria-label="台账月份"/><span>本月收入 ¥{{money(income)}} / 支出 ¥{{money(expense)}} / 截至本月余额 ¥{{money(balance)}}</span></div>
    <el-table :data="transactions"><el-table-column prop="date" label="日期" width="130"/><el-table-column prop="title" label="收支事项" min-width="160"/><el-table-column label="收入"><template #default="{row}">{{row.amount>0?'¥'+money(row.amount):'—'}}</template></el-table-column><el-table-column label="支出"><template #default="{row}">{{row.amount<0?'¥'+money(-row.amount):'—'}}</template></el-table-column><el-table-column prop="note" label="备注" min-width="220" show-overflow-tooltip/></el-table>
   </section>
   <Accounts ref="accountsPage" v-else-if="section==='accounts' && can('account:edit')" :projects="data.projects" :refresh="refresh"/>
   <section v-else-if="section==='notifications'"><div class="table-heading"><h2>审批与处理消息</h2><div class="actions"><span>已读状态在三端同步</span><el-button :disabled="busy || !data.notifications.some(n=>!n.read)" @click="markAllRead">全部已读</el-button></div></div><el-table :data="data.notifications"><el-table-column prop="title" label="消息"/><el-table-column prop="detail" label="说明"/><el-table-column prop="time" label="时间"/><el-table-column label="状态"><template #default="{row}">{{row.read?'已读':'未读'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="openNotice(row)">查看单据</el-button></template></el-table-column></el-table></section>
   <el-empty v-else description="当前账号没有此页面权限"/>
  </template>
  <RecordForm v-if="formKind" :key="formKind+(editRecord?.id||'new')" :kind="formKind" :data="data" :project-id="projectId" :record="editRecord" :write="write" @close="formKind=''" @saved="showRecord"/>
  <RecordDetail v-if="detail" :key="detail.id" :record="detail" :data="data" :can="can" :write="write" @close="detail=null" @edit="editApplication"/>
  <MasterEditor v-if="master" :type="master.type" :value="master.value" :project-id="projectId" :write="write" @close="master=null"/>
  <el-drawer class="shipyard-dialog" v-model="ledgerOpen" title="登记其他收支" size="min(540px,96vw)"><el-form label-position="top"><el-form-item label="收支类型"><el-radio-group v-model="entry.direction"><el-radio value="收入">收入</el-radio><el-radio value="支出">支出</el-radio></el-radio-group></el-form-item><el-form-item label="事项名称"><el-input v-model="entry.title" aria-label="收支事项" maxlength="100"/></el-form-item><el-form-item label="金额"><el-input-number v-model="entry.amount" :min="0.01" :precision="2" aria-label="收支金额"/></el-form-item><el-form-item label="业务日期"><el-date-picker v-model="entry.date" value-format="YYYY-MM-DD" aria-label="收支日期"/></el-form-item><el-form-item label="备注"><el-input v-model="entry.note" type="textarea" maxlength="500" aria-label="收支备注"/></el-form-item></el-form><template #footer><el-button type="primary" :loading="busy" @click="saveLedger">保存收支</el-button></template></el-drawer>
 </main>
</template>
<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useShipyard} from './useShipyard'
import {money,exportCsv,requestKey,shipyardApi} from '@/api/shipyard'
import RecordForm from './components/RecordForm.vue'
import RecordDetail from './components/RecordDetail.vue'
import MasterEditor from './components/MasterEditor.vue'
import Accounts from './components/Accounts.vue'
const {data,loading,ready,error,projectId,project,month,updated,busy,can,scoped,refresh,write,act}=useShipyard(),route=useRoute(),router=useRouter()
const section=computed(()=>route.params.section||'workbench')
const tabs=computed(()=>[
 {id:'workbench',label:'工作台'}, {id:'projects',label:'工程与人员'}, {id:'records',label:'申请与审批'},
 ...(can('finance:view')||can('payroll:pay')?[{id:'attendance',label:'每日出勤'},{id:'payroll',label:'工资结算'}]:[]),
 ...(can('finance:view')||can('payroll:pay')||can('ledger:edit')?[{id:'ledger',label:'收支台账'}]:[]),
 {id:'archive',label:'完工归档'},...(can('account:edit')?[{id:'accounts',label:'账号权限'}]:[]),{id:'notifications',label:'消息'}])
const activeLabel=computed(()=>tabs.value.find(t=>t.id===section.value)?.label||'船厂工作台')
watch([ready,tabs,section],()=>{if(ready.value&&!tabs.value.some(t=>t.id===section.value))navigate('workbench')})
function navigate(id){router.push('/shipyard/workspace/'+id)}
const formKind=ref(''),editRecord=ref(null),detail=ref(null),master=ref(null),personSearch=ref(''),search=ref(''),kind=ref(''),status=ref(''),recordMonth=ref(''),attendanceDate=ref(''),archiveMonth=ref(''),selected=ref([]),ledgerOpen=ref(false),entry=ref({}),payrollTable=ref(null),accountsPage=ref(null),recordAreaId=ref('')
const statuses=['待审批','待负责人签字','待结算','已结算','待付款','已付款','会计待处理','已处理','已退回']
watch(()=>data.serverDate,date=>{if(!attendanceDate.value)attendanceDate.value=date})
watch([projectId,month,section],()=>{selected.value=[];payrollTable.value?.clearSelection()})
watch(projectId,()=>{recordAreaId.value=''})
const people=computed(()=>(can('master:edit')?(data.workerArchive ?? data.people):data.people).filter(p=>[p.name,p.code,p.team].join(' ').includes(personSearch.value)))
const records=computed(()=>scoped(data.records).filter(r=>(!recordAreaId.value||Number(r.areaId)===Number(recordAreaId.value))&&(!kind.value||r.kind===kind.value)&&(!status.value||r.status===status.value)&&(!recordMonth.value||(r.paidDate||r.date).startsWith(recordMonth.value))&&[r.id,r.note,r.author,r.area].join(' ').includes(search.value)))
function reviewable(r){if(r.createdBy===data.user.id)return false;if(r.status==='待负责人签字')return can('expense:confirm')&&r.managerId!==data.user.id;return r.status==='待审批'&&can(r.kind==='用工'?'work:approve':r.kind==='罚款'?'fine:approve':'expense:approve')}
const tasks=computed(()=>scoped(data.records).filter(r=>reviewable(r)||(r.status==='待付款'&&can('expense:pay'))||(r.status==='会计待处理'&&can('fine:handle'))||(r.status==='待结算'&&can('payroll:pay'))||(r.status==='已退回'&&r.createdBy===data.user.id)))
const attendance=computed(()=>scoped(data.attendance).filter(r=>String(r.date).slice(0,10)===attendanceDate.value)),attendanceWorkers=computed(()=>new Set(attendance.value.map(r=>r.workerId)).size)
const archiveStart=computed(()=>{const [y,m]=data.serverDate.split('-').map(Number);const d=new Date(y,m-3,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01'})
const archives=computed(()=>scoped(data.areas).filter(a=>a.completedAt&&String(a.completedAt).slice(0,10)>=archiveStart.value&&(!archiveMonth.value||String(a.completedAt).startsWith(archiveMonth.value))))
const payroll=computed(()=>scoped(data.payroll).filter(p=>p.month===month.value)),selectedTotal=computed(()=>selected.value.filter(p=>!p.paid).reduce((s,p)=>s+p.amount,0))
const transactions=computed(()=>scoped(data.transactions).filter(t=>t.date.startsWith(month.value))),income=computed(()=>transactions.value.filter(t=>t.amount>0).reduce((s,t)=>s+t.amount,0)),expense=computed(()=>-transactions.value.filter(t=>t.amount<0).reduce((s,t)=>s+t.amount,0)),balance=computed(()=>scoped(data.transactions).filter(t=>t.date.slice(0,7)<=month.value).reduce((s,t)=>s+t.amount,0))
function newRecord(type){editRecord.value=null;formKind.value=type}
function editApplication(item){detail.value=null;editRecord.value=item;formKind.value=item.kind}
function showRecord(row){detail.value=JSON.parse(JSON.stringify(row))}
function editMaster(type,value){master.value={type,value}}
async function refreshPage(){await refresh();await accountsPage.value?.reload()}
function toggleWorker(row){act(async()=>{const active=Number(row.active ?? 1)===1?0:1;await ElMessageBox.confirm(active?'确认恢复 '+row.name+'？恢复后可再次选择安排施工。':'确认停用 '+row.name+'？停用后不再出现在新申请人员列表，历史工资与单据保留。',active?'恢复人员':'停用人员');await write('/master/person',{...row,active},'PUT');ElMessage.success(active?'人员已恢复':'人员已停用')})}
function complete(row){act(async()=>{await ElMessageBox.confirm('确认 '+row.name+' 已施工完工？财务结算仍可继续处理。','施工完工');await write('/areas/'+row.id+'/complete',{});ElMessage.success('已归档')})}
function requestCompletion(row){act(async()=>{await ElMessageBox.confirm('确认 '+row.name+' 已完成施工，提交项目经理确认？确认前该区域暂停新增用工。','提交完工');await write('/areas/'+row.id+'/completion-request',{});ElMessage.success('已提交，等待项目经理确认')})}
function rejectCompletion(row){act(async()=>{const {value}=await ElMessageBox.prompt('请填写退回原因','退回完工申请',{inputValidator:v=>!!String(v||'').trim()&&String(v).trim().length<=200,inputErrorMessage:'请填写退回原因，不超过200字'});await write('/areas/'+row.id+'/completion-reject',{reason:String(value).trim()});ElMessage.success('已退回')})}
let paymentRequest={fingerprint:'',key:''}
watch(payroll,rows=>{for(const row of selected.value)if(!rows.some(p=>p.id===row.id&&!p.paid))payrollTable.value?.toggleRowSelection(row,false)},{flush:'post'})
function settle(){act(async()=>{const selectedProject=projectId.value,selectedMonth=month.value,amountToPay=selectedTotal.value;const lineIds=selected.value.filter(p=>!p.paid).map(p=>p.id).sort((a,b)=>a-b);if(!lineIds.length)return;const fingerprint=JSON.stringify([selectedProject,selectedMonth,lineIds]);if(paymentRequest.fingerprint!==fingerprint)paymentRequest={fingerprint,key:requestKey()};await ElMessageBox.confirm('确认已实际支付 ¥'+money(amountToPay)+' 的工资？','登记工资结算');const amount=await write('/payroll/settle',{projectId:selectedProject,month:selectedMonth,lineIds,requestKey:paymentRequest.key});selected.value=[];ElMessage.success('已登记工资 ¥'+money(amount))})}
function openLedger(){entry.value={projectId:projectId.value,direction:'收入',title:'',amount:0,date:data.serverDate,note:'',requestKey:requestKey()};ledgerOpen.value=true}
function saveLedger(){act(async()=>{await write('/ledger',{...entry.value,amount:Number(entry.value.amount)*(entry.value.direction==='支出'?-1:1)});ledgerOpen.value=false;ElMessage.success('收支已保存')})}
function markAllRead(){act(async()=>{try{for(const notice of data.notifications.filter(n=>!n.read)){await shipyardApi('/notices/'+notice.id+'/read','POST',{});notice.read=true}ElMessage.success('已全部标为已读')}finally{await refresh().catch(()=>ElMessage.warning('消息已更新，刷新失败，请重新加载'))}})}
function openNotice(n){act(async()=>{const item=await shipyardApi('/records/'+n.recordId);await write('/notices/'+n.id+'/read',{});showRecord(item)})}
function exportRecords(){exportCsv('申请与审批',[['单号','工程','区域','类型','申请人','日期','付款日期','金额','状态','说明','被罚人员','工号','班组'],...records.value.map(r=>{const person=r.kind==='罚款'?(r.personSnapshot||data.people.find(p=>p.id===r.person)||{}):{};return [r.id,r.ship,r.area,r.kind,r.author,r.date,r.paidDate,r.amount,r.status,r.note,person.name,person.code,person.team]})])}
function exportAttendance(){exportCsv('每日出勤',[['日期','工程','区域','姓名','工号','班组','工时'],...attendance.value.map(r=>[attendanceDate.value,project.value?.name,data.areas.find(a=>String(a.id)===String(r.areaId))?.name,r.name,r.code,r.team,r.hours])])}
function exportPayroll(){exportCsv('工资明细',[['工程','月份','工人','类型','工时','时薪快照','倍率','金额','状态','付款批次'],...payroll.value.map(p=>[p.ship,p.month,p.name,p.label,p.hours,p.rate,p.multiplier,p.amount,p.paid?'已结算':'待结算',p.paymentId])])}
function exportLedger(){exportCsv('收支台账',[['日期','工程','事项','收入','支出','备注'],...transactions.value.map(t=>[t.date,t.ship,t.title,t.amount>0?t.amount:'',t.amount<0?-t.amount:'',t.note])])}
</script>
