-date-editor{width:100%}.file-line{display:flex;align-items:center;justify-content:space-between;width:100%}.record-heading{display:flex;align-items:center;gap:20px;margin:10px 0 22px}.record-heading strong{font-size:28px}.action-row{display:flex;justify-content:flex-end;gap:12px;margin-top:18px}.shipyard-admin .el-alert{margin-bottom:18px}.shipyard-admin .el-table{border-radius:8px;--el-table-header-bg-color:#f1f6f8;--el-table-header-text-color:#486173}.shipyard-admin .el-table .cell{line-height:25px}.shipyard-admin .el-table th{font-weight:600}.shipyard-admin .el-descriptions__label{font-weight:500!important}.shipyard-admin input[type=file]{max-width:100%}@media(max-width:1000px){.shipyard-admin{padding:16px}.workspace-header{align-items:flex-start;flex-direction:column}.table-heading{align-items:flex-start;flex-direction:column}.workspace-nav button{padding:9px 10px}.workspace-controls{width:100%}.form-columns{grid-template-columns:1fr}}
</style>
